#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>

static void probe(const char *exe, const char *n) {
    int fds[2];
    if (pipe(fds)) { perror("pipe"); exit(1); }
    pid_t pid = fork();
    if (pid == 0) {
        close(fds[0]);
        dup2(fds[1], 1);
        close(fds[1]);
        execl(exe, exe, n, (char*)NULL);
        _exit(127);
    }
    close(fds[1]);
    char buf[1];
    read(fds[0], buf, 1);   /* consume exactly one byte */
    close(fds[0]);          /* reader gone */
    int st = 0;
    waitpid(pid, &st, 0);
    if (WIFSIGNALED(st))
        printf("  %-42s killed by signal %d (%s)\n", exe, WTERMSIG(st), strsignal(WTERMSIG(st)));
    else
        printf("  %-42s exited normally, code %d\n", exe, WEXITSTATUS(st));
}

int main(int argc, char **argv) {
    const char *ns[] = {"7", "20000"};
    for (int i = 0; i < 2; i++) {
        printf("n=%s\n", ns[i]);
        probe("/workspace/dataset/test7_executable", ns[i]);
        probe("/output/test7", ns[i]);
    }
    return 0;
}
EOF
