#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <sys/wait.h>

/* Start target with stdout = pipe we never drain. Once >64KiB is produced the
   target blocks in write(), i.e. it is past runtime init. Then read SigIgn. */
static void dispo(const char *exe, const char *n) {
    int fds[2];
    if (pipe(fds)) { perror("pipe"); exit(1); }
    pid_t pid = fork();
    if (pid == 0) {
        close(fds[0]); dup2(fds[1], 1); close(fds[1]);
        execl(exe, exe, n, (char*)NULL); _exit(127);
    }
    close(fds[1]);
    sleep(2);                       /* let it run and block on a full pipe */
    char path[64], line[256];
    snprintf(path, sizeof path, "/proc/%d/status", (int)pid);
    FILE *f = fopen(path, "r");
    printf("%s (n=%s)\n", exe, n);
    if (!f) { printf("  <process already gone>\n"); }
    else {
        while (fgets(line, sizeof line, f))
            if (!strncmp(line, "SigIgn", 6) || !strncmp(line, "SigCgt", 6)) {
                line[strcspn(line, "\n")] = 0;
                unsigned long long m = strtoull(strchr(line, '\t') + 1, NULL, 16);
                printf("  %s   SIGPIPE(13) bit set: %s\n", line,
                       (m & (1ULL << 12)) ? "YES" : "no");
            }
        fclose(f);
    }
    kill(pid, SIGKILL);
    int st; waitpid(pid, &st, 0);
}

int main(void) {
    dispo("/workspace/dataset/test7_executable", "200000");
    dispo("/output/test7", "200000");
    return 0;
}
EOF
