#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

static int probe(const char *exe, const char *n) {
    int fds[2]; if (pipe(fds)) exit(1);
    pid_t pid = fork();
    if (pid == 0) { close(fds[0]); dup2(fds[1],1); close(fds[1]);
                    execl(exe, exe, n, (char*)NULL); _exit(127); }
    close(fds[1]);
    char b[1]; read(fds[0], b, 1); close(fds[0]);
    int st; waitpid(pid, &st, 0);
    return WIFSIGNALED(st) ? 128 + WTERMSIG(st) : WEXITSTATUS(st);
}

int main(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        int c = probe("/workspace/dataset/test7_executable", argv[i]);
        int r = probe("/output/test7", argv[i]);
        printf("n=%-8s cpp=%-4d rust=%-4d %s\n", argv[i], c, r,
               c == r ? "match" : "*** DIVERGE ***");
    }
    return 0;
}
